        sum_r = sum(r_tuple)
        sum_c = target_sum - sum_r

        rn = r_tuple[-1]
        cn = n**2 - rn

        if cn < n: continue

        rem_sum = sum_c - 1 - cn

        def find_subsets(target, count, min_val, max_val):
            if count == 0:
                return [[]] if target == 0 else []
            if min_val > max_val or target < count * min_val:
                return []
            res = []
            for i in range(min_val, max_val + 1):
                subsets = find_subsets(target - i, count - 1, i + 1, max_val)
                for s in subsets:
                    res.append([i] + s)
            return res

        subsets = find_subsets(rem_sum, n - 2, 2, cn - 1)

        for s in subsets:
            c_tuple = sorted([1] + s + [cn])
            vals = set()
            for r in r_tuple:
                for c in c_tuple:
                    vals.add(r + c)
            if len(vals) == n**2 and max(vals) == n**2 and min(vals) == 1:
                good_pairs.append((r_tuple, c_tuple))

    return good_pairs

