    limit = n*n
    # X = {x_0, ..., x_{n-1}}, Y = {y_0, ..., y_{n-1}}
    # x_0 = 0, y_0 = 0
    # x_0 < x_1 < ... < x_{n-1}
    # y_0 < y_1 < ... < y_{n-1}
    # x_{n-1} + y_{n-1} = n^2 - 1

    # Let's just iterate over all possible X and Y.
    # For n=3, x_i \in {0, ..., 8}, y_j \in {0, ..., 8}.
    # Number of ways to choose X is (9 choose 3) = 84.
    # Total pairs of (X, Y) is 84 * 84 = 7056.
    # This is small!

    count = 0
    for X in itertools.combinations(range(limit), n):
        if X[0] != 0: continue
        for Y in itertools.combinations(range(limit), n):
            if Y[0] != 0: continue
            # Check if X+Y = {0, ..., n^2-1}
            sums = set()
            for x in X:
                for y in Y:
                    s = x + y
                    if s >= limit or s in sums:
                        break
                    sums.add(s)
                else:
                    continue
                break
            else:
                if len(sums) == n*n:
                    count += 1
    return count

